SELECT ROUND(SUM(budget_amount), 2) AS total_budget
FROM campaigns
WHERE campaign_type = 'Awareness';

SELECT ROUND(SUM(budget_amount), 2) AS total_budget
FROM campaigns
WHERE campaign_type = 'Awareness';

SELECT COUNT(*) AS account_count
FROM accounts a LEFT JOIN contacts c ON a.account_id = c.account_id
WHERE a.region = 'Central' AND c.contact_id IS NULL;

SELECT COUNT(*) AS contact_count
FROM contacts c LEFT JOIN interactions i ON c.contact_id = i.contact_id
WHERE c.title = 'Business Analyst' AND i.interaction_id IS NULL;

SELECT COUNT(s.case_id) AS case_count
FROM support_cases s INNER JOIN accounts a ON s.account_id = a.account_id
WHERE a.region = 'Central';

SELECT COUNT(c.contact_id) AS contact_count
FROM contacts c INNER JOIN accounts a ON c.account_id = a.account_id
WHERE a.industry = 'Education';

SELECT COUNT(*) AS case_count
FROM support_cases
WHERE priority = 'Critical';

SELECT COUNT(*) AS interaction_count
FROM interactions
WHERE engagement_type = 'EmailOpen';
